   -1.65597368172179971E-03_R8P, -1.64286131872273312E-03_R8P, -1.62937223615766615E-03_R8P, &
   -1.61554398951057449E-03_R8P, -1.60141323228034393E-03_R8P, -1.58701554840029219E-03_R8P, &
   -1.57238531040236910E-03_R8P, -1.55755556250405328E-03_R8P, -1.54255792743822405E-03_R8P, &
   -1.52742253556764043E-03_R8P, -1.51217797462159325E-03_R8P, -1.49685125825644292E-03_R8P, &
   -1.48146781156658649E-03_R8P, -1.46605147164965998E-03_R8P, -1.75837678860291872E-03_R8P, &
   -1.75794741802424190E-03_R8P, -1.75666119491457262E-03_R8P, -1.75452376204862279E-03_R8P, &
   -1.75154444759129634E-03_R8P, -1.74773615232849937E-03_R8P, -1.74311519555256670E-03_R8P, &
   -1.73770112318687620E-03_R8P, -1.73151648251623248E-03_R8P, -1.72458656850952002E-03_R8P, &
   -1.71693914716252111E-03_R8P, -1.70860416154474401E-03_R8P, -1.69961342630656101E-03_R8P, &
   -1.69000031630228221E-03_R8P, -1.67979945472831386E-03_R8P, -1.66904640578596818E-03_R8P, &
   -1.65777737638211778E-03_R8P, -1.64602893080590534E-03_R8P, -1.63383772169437003E-03_R8P, &
   -1.62124023995109602E-03_R8P, -1.60827258563434245E-03_R8P, -1.59497026120563744E-03_R8P, &
   -1.58136798794384931E-03_R8P, -1.56749954579643233E-03_R8P, -1.55339763646812298E-03_R8P, &
   -1.53909376914313899E-03_R8P, -1.52461816790209689E-03_R8P, -1.50999969962846881E-03_R8P, &
   -1.49526582099847771E-03_R8P, -1.48044254300796845E-03_R8P, -1.46555441140401306E-03_R8P, &
   -1.45062450135100625E-03_R8P, -1.43567442466376429E-03_R8P /

contains
   pure function lattice_green(n) result(g)
   !< Return the lattice Green's function of the 7-point Laplacian at the lattice offset `n`.
   integer(I4P), intent(in) :: n(3)    !< Lattice offset.
   real(R8P)                :: g       !< G(n).
   integer(I4P)             :: a, b, c !< |n| sorted, a >= b >= c.
   integer(I4P)             :: t       !< Swap.
   real(R8P)                :: x(3)    !< |n| sorted, real.
   real(R8P)                :: r2, r   !< |n|^2, |n|.
   real(R8P)                :: p8      !< G2's polynomial.
   real(R8P)                :: p12     !< G3's polynomial.
   real(R8P)                :: s2(3)   !< x^2.

   a = abs(n(1)) ; b = abs(n(2)) ; c = abs(n(3))
   if (a < b) then ; t = a ; a = b ; b = t ; endif
   if (b < c) then ; t = b ; b = c ; c = t ; endif
   if (a < b) then ; t = a ; a = b ; b = t ; endif
   if (a <= LGF_RADIUS) then
      g = LGF_TABLE(a * (a + 1) * (a + 2) / 6 + b * (b + 1) / 2 + c + 1)
   else
      x = [real(a, R8P), real(b, R8P), real(c, R8P)]
      r2 = sum(x**2)
      r = sqrt(r2)
      p8 = G2_C(1) * sum(x**8) + &
           G2_C(2) * (x(1)**6 * (x(2)**2 + x(3)**2) + x(2)**6 * (x(1)**2 + x(3)**2) + x(3)**6 * (x(1)**2 + x(2)**2)) + &
           G2_C(3) * (x(1)**4 * x(2)**4 + x(2)**4 * x(3)**4 + x(3)**4 * x(1)**4) + &
           G2_C(4) * x(1)**2 * x(2)**2 * x(3)**2 * r2
      s2 = x**2
      p12 = G3_C(1) * sum(s2**6) + &
            G3_C(2) * (s2(1)**5 * (s2(2) + s2(3)) + s2(2)**5 * (s2(1) + s2(3)) + s2(3)**5 * (s2(1) + s2(2))) + &
            G3_C(3) * (s2(1)**4 * (s2(2)**2 + s2(3)**2) + s2(2)**4 * (s2(1)**2 + s2(3)**2) + &
                       s2(3)**4 * (s2(1)**2 + s2(2)**2)) + &
            G3_C(4) * (s2(1)**4 * s2(2) * s2(3) + s2(2)**4 * s2(1) * s2(3) + s2(3)**4 * s2(1) * s2(2)) + &
            G3_C(5) * (s2(1)**3 * s2(2)**3 + s2(2)**3 * s2(3)**3 + s2(3)**3 * s2(1)**3) + &
            G3_C(6) * s2(1) * s2(2) * s2(3) * (s2(1)**2 * (s2(2) + s2(3)) + s2(2)**2 * (s2(1) + s2(3)) + &
                                               s2(3)**2 * (s2(1) + s2(2))) + &
            G3_C(7) * (s2(1) * s2(2) * s2(3))**2
      g = -1._R8P / (4._R8P * PI * r) - 5._R8P * (sum(x**4) - 0.6_R8P * r2 * r2) / (32._R8P * PI * r**7) + p8 / r**13 + &
          p12 / r**19
   endif
   endfunction lattice_green
endmodule adam_lattice_green_library
